/* @socom-skeleton body zrdr_tobool__FPC5_zrdrPb */
bool zrdr_tobool(const _zrdr *reader, bool *output)
{
	/* 0x23d570: an integer (non-zero) or the strings true/on, false/off; an array of at least
	 * one value reads its first value (array[1]; array[0] holds the count). True when a value
	 * was read. Without an output the value goes to a local. (Was: an array read its count,
	 * so every array value - looped (0), disabled (false) - read true; an integer returned
	 * false; no output returned false.) */
	bool dummy;

	if (!output)
		output = &dummy;

	if (!reader)
		return false;

	if (reader->type == ZRDR_ARRAY && reader->array->integer >= 2)
		reader = &reader->array[1];

	if (reader->type == ZRDR_INTEGER)
	{
		*output = reader->integer != 0;
		return true;
	}

	if (reader->type == ZRDR_STRING)
	{
		if (strcasecmp(reader->string, "true") == 0 || strcasecmp(reader->string, "on") == 0)
		{
			*output = true;
			return true;
		}
		else if (strcasecmp(reader->string, "false") == 0 || strcasecmp(reader->string, "off") == 0)
		{
			*output = false;
			return true;
		}
	}

	return false;
}

/* @socom-skeleton body zrdr_toINT__FPC5_zrdrPii */
bool zrdr_toINT(const _zrdr *reader, int *output, int size)
{
	if (!reader)
		return false;

	if (reader->type != ZRDR_ARRAY)
		return false;

	if (reader->array->integer < size + 1)
		return false;

	for (u32 i = 1; i < size + 1; i++)
	{
		s32 integer = 0;
		_zrdr* node = &reader->array[i];

		if (node->type == ZRDR_REAL)
			integer = static_cast<s32>(node->real);

		if (node->type == ZRDR_INTEGER)
			integer = node->integer;

		*output = integer;
	}

	return true;
}

