/* @socom-skeleton body zrdr_findSTRING__FPC5_zrdrPCcPPCc */
bool zrdr_findSTRING(const _zrdr *reader, const char *name, const char **list)
{
	auto tag = zrdr_findtag_startidx(reader, name, 1);

	if (!tag)
		return false;

	if (!list)
		return false;

	/* 0x23d328: a value in parentheses is its first element - the array's element count is
	 * its first node's integer (lw 4(array)); was the header's 16-bit length field, which a
	 * parsed array leaves 0, so NAME ("x") never matched (materials.rdr's soils) */
	if (tag->type == ZRDR_ARRAY)
	{
		if (tag->array->integer > 1)
			tag = &tag->array[1];
	}

	if (tag->type == ZRDR_STRING)
	{
		*list = tag->string;
		return true;
	}

	if (tag->type == ZRDR_INTEGER && tag->integer == 0)
	{
		*list = NULL;
		return true;
	}

	return false;
}

/* @socom-skeleton body zrdr_findPNT3D__FPC5_zrdrPCcP5PNT3D */
bool zrdr_findPNT3D(const _zrdr *reader, const char *name, PNT3D *output)
{
	_zrdr* tag = zrdr_findtag_startidx(reader, name, 1);

	if (!tag)
		return false;

	if (tag->type != ZRDR_ARRAY)
		return false;

	if (tag->array->integer < 3)
		return false;

	f32 axis = 0.0f;

	for (u32 i = 0; i < 3; i++)
	{
		_zrdr* node = &tag->array[1];

		if (node[i].type == ZRDR_REAL)
			axis = node[i].real;

		if (node[i].type == ZRDR_INTEGER)
			axis = static_cast<f32>(node[i].integer);

		(&output->x)[i] = axis;
	}

	return true;
}

